module top_module(
  input clk,
  input rst,
  input we,
  input re,
  input [data_width-1:0] din,
  output [data_width-1:0] dout,
  output empty,
  output full
);parameter data_width = 8; // width of data bus
parameter depth = 16; // depth of FIFO

reg [data_width-1:0] mem [0:depth-1]; // FIFO memory
reg [4:0] read_ptr; // read pointer
reg [4:0] write_ptr; // write pointer
wire [4:0] next_write_ptr; // next write pointer
wire [4:0] next_read_ptr; // next read pointer

// Remove redeclaration of empty and full as wires, since they are outputs
assign empty = (read_ptr == write_ptr);
assign full = (next_write_ptr == read_ptr);

always @(posedge clk) begin
  if (rst) begin
    read_ptr <= 0;
    write_ptr <= 0;
  end else begin
    read_ptr <= next_read_ptr;
    write_ptr <= next_write_ptr;
  end
end

assign dout = mem[read_ptr];

assign next_read_ptr = (re && !empty) ? read_ptr + 1 : read_ptr;
assign next_write_ptr = (we && !full) ? write_ptr + 1 : write_ptr;

always @(posedge clk) begin
  if (rst) begin
    // Using a for loop to reset memory
    integer i;
    for (i = 0; i < depth; i = i + 1) begin
      mem[i] <= 0;
    end
  end else if (we && !full) begin
    mem[write_ptr] <= din;
  end
end

endmodule

