module top_module(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [9:0]   data_out
);reg [7:0] shift_reg [2:0];
reg [9:0] acc_reg;
reg [1:0] count;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        acc_reg <= 10'b0;
        count <= 2'b0;
        valid_b <= 1'b0;
        data_out <= 10'b0;
        shift_reg[0] <= 8'b0;
        shift_reg[1] <= 8'b0;
        shift_reg[2] <= 8'b0;
    end
    else begin
        if(valid_a && ready_b) begin
            shift_reg[0] <= data_in;
            shift_reg[1] <= shift_reg[0];
            shift_reg[2] <= shift_reg[1];
            acc_reg <= acc_reg + data_in;
            count <= count + 1;
            if(count == 2) begin
                data_out <= acc_reg;
                valid_b <= 1'b1;
                count <= 2'b0;
            end
            else begin
                valid_b <= 1'b0;
            end
        end
        else begin
            valid_b <= 1'b0;
        end
    end
end

assign ready_a = ~valid_b;

endmodule

