description:
Design a 4-bit binary counter that counts in a specific sequence based on a clock input. The counter transitions through a predefined state sequence with each rising edge of the clock and counts in the following order: 1, 2, 4, 8, and then resets to 1. The counter also has an active-low reset input, which when asserted, initializes the counter and its state to zero. The output is a 4-bit representation of the current count value.
module top_module(
    input CLK,
    input RESET_B,
    output [3:0] COUNT
);

code:
module top_module(
    input CLK,
    input RESET_B,
    output [3:0] COUNT
);reg [1:0] state;
    reg [3:0] count;

    always @(posedge CLK) begin
        if (!RESET_B) begin
            state <= 2'b00;
            count <= 4'b0000;
        end else begin
            case (state)
                2'b00: begin
                    count <= 4'b0001;
                    state <= 2'b01;
                end
                2'b01: begin
                    count <= 4'b0010;
                    state <= 2'b10;
                end
                2'b10: begin
                    count <= 4'b0100;
                    state <= 2'b11;
                end
                2'b11: begin
                    count <= 4'b1000;
                    state <= 2'b00;
                end
            endcase
        end
    end

    assign COUNT = count;

endmodule

