description:
Design a clock divider circuit that takes an input clock signal (clk_in) and produces a reduced frequency output clock signal (clk_out) based on a specified division factor, which is set to 2 by default. The circuit features a synchronous reset (rst) that initializes the counter and the output clock to zero when asserted. The internal counter increments with each rising edge of clk_in and toggles clk_out every time the counter reaches the division factor minus one, effectively halving the frequency of the input clock signal.
module top_module(
  input clk_in, rst,
  output reg clk_out
);

code:
module top_module(
  input clk_in, rst,
  output reg clk_out
);parameter div_factor = 2; // divide by 2

reg [31:0] counter;

always @(posedge clk_in or posedge rst) begin
  if (rst) begin
    counter <= 0;
    clk_out <= 0;
  end else begin
    counter <= counter + 1;
    if (counter == div_factor - 1) begin
      counter <= 0;
      clk_out <= ~clk_out;
    end
  end
end

endmodule

