module top_module( 
    input clk,
    input areset,  // async active-high reset to zero
    input load,
    input ena,
    input select, // select input to choose between shift register and barrel shifter
    input [3:0] data, // 4-bit input for the shift register
    input [7:0] barrel_in, // 8-bit input for the barrel shifter
    output reg [7:0] out // 8-bit output from the functional module
);reg [3:0] shift_reg;
reg [3:0] shifted_data;
reg [3:0] adder_out;
reg [3:0] lower_nibble;
reg [3:0] upper_nibble;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        shift_reg <= 4'b0;
        shifted_data <= 4'b0;
        adder_out <= 4'b0;
        lower_nibble <= 4'b0;
        upper_nibble <= 4'b0;
        out <= 8'b0;
    end else begin
        if (load) begin
            shift_reg <= data;
        end else if (ena) begin
            shift_reg <= {1'b0, shift_reg[3:1]};
        end

        if (select) begin
            lower_nibble <= barrel_in[3:0];
            upper_nibble <= barrel_in[7:4];
            shifted_data <= shift_reg;
        end else begin
            lower_nibble <= shifted_data;
            upper_nibble <= barrel_in[7:4];
            shifted_data <= {1'b0, shifted_data[3:1]};
        end

        adder_out <= shifted_data + lower_nibble;
        out <= {upper_nibble, adder_out};
    end
end

endmodule

