   input clk, reset, next,
   input [4:0] i1,
   input [11:0] X0,
                 X1,
                 X2,
                 X3,
   output reg [11:0] Y0,
                     Y1,
                     Y2,
                     Y3,
   output next_out);reg [9:0] i2;
   reg [11:0] sum;

   always @(posedge clk) begin
      if (reset == 1) begin
         i2 <= 0;
         Y0 <= 0;
         Y1 <= 0;
         Y2 <= 0;
         Y3 <= 0;
      end
      else begin
         if (next == 1)
