description:
Design a data register module that captures an 8-bit input data and its associated validity signal on the rising edge of a clock. When reset is asserted, the module outputs zero for both data_out and valid_out. Otherwise, it passes the input data and validity signal to the outputs, allowing the stored values to be synchronously updated.
module top_module(

   data_out, valid_out,

   clk, rst, data_in, valid_in
   ) ;

code:
module top_module(

   data_out, valid_out,

   clk, rst, data_in, valid_in
   ) ;input clk;
   input rst;
   input [7:0] data_in;
   input valid_in;
   output [7:0] data_out;
   output valid_out;

   reg [7:0]		data_out;
   reg			valid_out;

   always @(posedge clk or posedge rst) begin
      if (rst) begin
	 data_out <= 'h0;
	 valid_out <= 'h0;
      end
      else begin
	 data_out <= data_in;
	 valid_out <= valid_in;
      end
   end
endmodule

