module top_module (
        input clk,
        input areset,
        input open_button,
        input open_complete,
        input close_button,
        input close_complete,
        output reg door_open);parameter Closed=2'b00, Opening=2'b01, Open=2'b10, Closing=2'b11;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Closed;
		else begin
			case (state)
				Closed: state <= open_button ? Opening : Closed;
				Opening: state <= open_complete ? Open : Opening;
				Open: state <= close_button ? Closing : Open;
				Closing: state <= close_complete ? Closed : Closing;
			endcase
		end
	end

	assign door_open = (state == Open);

endmodule

