description:
Design a pulse generator that produces a 1 kHz square wave output from a 50 MHz clock input. The module includes a reset input that initializes the pulse output to LOW and resets the internal counter. When the reset is not asserted, the counter increments on each clock cycle, and the pulse output toggles whenever the counter reaches half the period required for a 1 kHz signal, effectively generating a square wave with a duty cycle of 50%.
module top_module(
    input clk,      // Added clk input
    input reset,
    output reg pulse
);

code:
module top_module(
    input clk,      // Added clk input
    input reset,
    output reg pulse
);reg [24:0] counter;
    parameter CLK_FREQ = 50_000_000; // 50 MHz clock frequency
    parameter PULSE_FREQ = 1_000; // 1 kHz pulse frequency

    always @(posedge clk) begin
        if (reset) begin
            pulse <= 0;
            counter <= 0;
        end
        else begin
            counter <= counter + 1;
            if (counter >= (CLK_FREQ/PULSE_FREQ)/2) begin
                pulse <= ~pulse;
                counter <= 0;
            end
        end
    end

endmodule

