module fsm (
    input clk,
    input reset,
    input g,
    output reg v);

    parameter Z1=0, Z2=1, Z3=2;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= Z1;
        else state <= next;
    end

    always_comb begin
        case (state)
            Z1: next = g ? Z2 : Z1;
            Z2: next = g ? Z2 : Z3;
            Z3: next = g ? Z2 : Z1;
            default: next = 'x;
        endcase
    end

    assign v = (state == Z3);

endmodule

