module top_module(
  input in_clk,
  input ref_clk,
  input reset,
  output out_clk,
  output locked
);parameter n = 8; // number of bits used to represent the phase accumulator
parameter m = 4; // number of bits used to represent the phase comparator output
parameter k = 2; // gain of the loop filter

reg [n-1:0] phase_acc; // phase accumulator
reg [m-1:0] phase_comp_out; // phase comparator output
reg [m-1:0] loop_filter_out; // loop filter output
reg locked_reg; // locked signal register

wire phase_comp_in; // phase comparator input
wire loop_filter_in; // loop filter input
wire [n-1:0] phase_acc_next; // next phase accumulator value
wire [m-1:0] phase_comp_out_next; // next phase comparator output value
wire [m-1:0] loop_filter_out_next; // next loop filter output value
wire locked_next; // next locked signal value

// phase comparator
assign phase_comp_in = in_clk ^ ref_clk;
assign phase_comp_out_next = phase_comp_in >> (m - 1);

// loop filter
assign loop_filter_in = phase_comp_out - (1 << (m - 1));
assign loop_filter_out_next = loop_filter_out + (k * loop_filter_in);

// phase accumulator
assign phase_acc_next = phase_acc + loop_filter_out_next;
assign out_clk = $signed(phase_acc_next[n-1]) ? ~in_clk : in_clk;
assign locked_next = (loop_filter_in == 0);

// locked signal register
always @(posedge in_clk, posedge reset) begin
  if (reset) begin
    locked_reg <= 0;
  end else begin
    locked_reg <= locked_next;
  end
end

// output assignments
assign phase_comp_out = phase_comp_out_next;
assign loop_filter_out = loop_filter_out_next;
assign phase_acc = phase_acc_next;
assign locked = locked_reg;

endmodule

