	if(first) begin
		r0r <= 7'd0;
		r1r <= 7'd0;
	end else if(next) begin
		if(r0r == hmesh_last) begin
			r0r <= 7'd0;
			r1r <= r1r + 7'd1;
		end else
			r0r <= r0r + 7'd1;
	end
end


always @(posedge sys_clk)
	last <= (r0r == hmesh_last) & (r1r == vmesh_last);

endmodule

